export type QueueTask = {
  id: string;
  title: string;
};

export const SECTION = {
  title: 'Close your next month with the queue already moving',
  description:
    'Use your work email and Tallyhand starts on the bank lines already waiting. The first close runs in review mode: nothing posts until you say so.',
  placeholder: 'you@company.com',
  emailLabel: 'Work email',
};

export const QUEUE = {
  title: 'Month-end queue',
  badge: 'Sample queue',
};

export const TASKS: QueueTask[] = [
  { id: 'match', title: 'Match 412 bank lines to invoices' },
  { id: 'chase', title: 'Ask for the 3 missing receipts' },
  { id: 'draft', title: 'Draft 9 journal entries' },
  { id: 'payroll', title: 'Check payroll against the ledger' },
  { id: 'handover', title: 'Hand the close over for review' },
];

import type { SessionStep } from '@/registry/ndeko/hooks/use-session';
import { keyDelayOf, prefixesOf } from '@/registry/ndeko/lib/demonstration';

import { TASKS } from './cta-data';

export type TaskStatus = 'open' | 'working' | 'done';

export type FormStatus = 'idle' | 'invalid' | 'sending' | 'sent';

export type CtaState = {
  email: string;
  form: FormStatus;
  /** Counts the refused submits, so a second refusal nudges the field again. */
  attempts: number;
  sentTo: string;
  tasks: TaskStatus[];
};

export type CtaAction =
  | { type: 'typed'; value: string }
  | { type: 'submitted' }
  | { type: 'sent' }
  | { type: 'reset' }
  | { type: 'working'; index: number }
  | { type: 'resolved'; index: number };

type Step = SessionStep<CtaState, CtaAction>;

const EMAIL_SHAPE = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;

export function isEmailLike(email: string) {
  return EMAIL_SHAPE.test(email.trim());
}

function allTasks(status: TaskStatus): TaskStatus[] {
  return TASKS.map(() => status);
}

export const INITIAL: CtaState = {
  email: '',
  form: 'idle',
  attempts: 0,
  sentTo: '',
  tasks: allTasks('open'),
};

function submitted(state: CtaState): CtaState {
  const isIdle = state.form === 'idle';
  const isRefused = state.form === 'invalid';
  const canSubmit = isIdle || isRefused;
  if (!canSubmit) {
    return state;
  }
  if (!isEmailLike(state.email)) {
    return { ...state, form: 'invalid', attempts: state.attempts + 1 };
  }
  return { ...state, form: 'sending' };
}

function sent(state: CtaState): CtaState {
  if (state.form !== 'sending') {
    return state;
  }
  return { ...state, form: 'sent', sentTo: state.email.trim() };
}

function withTask(
  state: CtaState,
  index: number,
  status: TaskStatus
): CtaState {
  const tasks = state.tasks.map((current, position) => {
    if (position === index) {
      return status;
    }
    return current;
  });
  return { ...state, tasks };
}

export function reducer(state: CtaState, action: CtaAction): CtaState {
  switch (action.type) {
    case 'typed':
      return { ...state, email: action.value, form: 'idle' };
    case 'submitted':
      return submitted(state);
    case 'sent':
      return sent(state);
    case 'reset':
      return { ...state, email: '', form: 'idle' };
    case 'working':
      return withTask(state, action.index, 'working');
    case 'resolved':
      return withTask(state, action.index, 'done');
  }
}

export function resolvedCountOf(state: CtaState) {
  const resolved = state.tasks.filter((status) => status === 'done');
  return resolved.length;
}

const TYPED_EMAIL = 'amina@lubumbashi-books.example';

const KEY_MS = 48;

/** How long the link takes to send, for the demonstration and for a person alike. */
export const SEND_MS = 1100;

function typing(text: string, startAfter: number): Step[] {
  const prefixes = prefixesOf(text);
  return prefixes.map((value, index) => ({
    after: keyDelayOf(index, startAfter, KEY_MS),
    by: 'demo',
    action: { type: 'typed', value },
  }));
}

function working(after: number, index: number): Step {
  return { after, action: { type: 'working', index } };
}

function resolved(after: number, index: number): Step {
  return { after, action: { type: 'resolved', index } };
}

/**
 * The queue clears on its own clock. Someone types an address and asks for the link while the
 * second task is being done, and the rest of the queue goes on after the link is sent.
 */
export const SCRIPT: Step[] = [
  working(1200, 0),
  resolved(1300, 0),
  working(600, 1),
  ...typing(TYPED_EMAIL, 500),
  resolved(500, 1),
  {
    after: 900,
    by: 'demo',
    press: 'submit',
    action: { type: 'submitted' },
  },
  working(1500, 2),
  resolved(1300, 2),
  working(700, 3),
  resolved(1200, 3),
  working(700, 4),
  resolved(1200, 4),
];

/** Under reduced motion the address is typed and the whole queue is cleared. */
export const RESTING: CtaState = {
  ...INITIAL,
  email: TYPED_EMAIL,
  tasks: allTasks('done'),
};

export const LOOP_AFTER_MS = 3600;

'use client';

import { useEffect, useId } from 'react';

import { useKeptHeight } from '@/registry/ndeko/hooks/use-kept-height';
import { useSession } from '@/registry/ndeko/hooks/use-session';
import { spokenUnless } from '@/registry/ndeko/lib/demonstration';
import { LiveRegion } from '@/registry/ndeko/ui/live-region';
import { ReplayButton } from '@/registry/ndeko/ui/replay-button';
import { Wash } from '@/registry/ndeko/ui/wash';

import { SECTION } from './cta-data';
import {
  INITIAL,
  LOOP_AFTER_MS,
  reducer,
  RESTING,
  resolvedCountOf,
  SCRIPT,
  SEND_MS,
  type CtaState,
} from './cta-session';
import { ANCHORS } from './data';
import { EmailForm } from './email-form';
import { QueueCard } from './queue-card';
import { SectionFrame } from './section-frame';

const SESSION = {
  reducer,
  initial: INITIAL,
  resting: RESTING,
  script: SCRIPT,
  loopAfter: LOOP_AFTER_MS,
};

function spokenLineOf(state: CtaState) {
  if (state.form === 'invalid') {
    return 'Enter an address like name@company.com';
  }
  if (state.form === 'sending') {
    return 'Sending your sign-in link';
  }
  if (state.form === 'sent') {
    return `We sent a sign-in link to ${state.sentTo}`;
  }
  return '';
}

export function Cta() {
  const { ref, isAutoplaying, state, act, pressed, isFinished, restart } =
    useSession(SESSION);
  const titleId = useId();
  const isSending = state.form === 'sending';
  const resolved = resolvedCountOf(state);
  const message = spokenUnless(isAutoplaying, spokenLineOf(state));
  const canReplay = isFinished && !isAutoplaying;

  useKeptHeight(ref);

  useEffect(() => {
    if (!isSending) {
      return;
    }
    const timer = setTimeout(() => act({ type: 'sent' }), SEND_MS);
    return () => clearTimeout(timer);
  }, [isSending, act]);

  return (
    <SectionFrame id={ANCHORS.start} ref={ref}>
      <div
        aria-labelledby={titleId}
        role='group'
        className='surface-brand relative isolate grid grid-cols-1 gap-8 rounded-2xl p-6 @2xl:p-10 @3xl:grid-cols-[minmax(0,1fr)_minmax(0,22rem)] @3xl:items-center @3xl:gap-12'
      >
        <Wash />
        <div className='flex flex-col gap-6'>
          <div className='flex max-w-xl flex-col gap-2'>
            <h2
              id={titleId}
              className='text-2xl font-semibold text-balance @2xl:text-3xl'
            >
              {SECTION.title}
            </h2>
            <p className='text-muted-foreground text-base text-pretty'>
              {SECTION.description}
            </p>
          </div>
          <EmailForm
            email={state.email}
            form={state.form}
            attempts={state.attempts}
            sentTo={state.sentTo}
            isPressed={pressed === 'submit'}
            onType={(value) => act({ type: 'typed', value })}
            onSubmit={() => act({ type: 'submitted' })}
            onReset={() => act({ type: 'reset' })}
          />
          <div className='flex'>
            <ReplayButton
              isShown={canReplay}
              onReplay={restart}
              label='Replay'
            />
          </div>
        </div>
        <QueueCard tasks={state.tasks} resolved={resolved} />
      </div>
      <LiveRegion message={message} />
    </SectionFrame>
  );
}

