        </span>
        <div className='flex min-w-0 flex-col leading-tight'>
          <p className='truncate text-[13px] font-medium'>
            Post 14 journal entries
          </p>
          <p className='text-muted-foreground truncate text-xs'>
            Asked by Reconciler
          </p>
        </div>
      </div>
      <Fold open={isWaiting}>
        <div className='flex gap-2 pt-1'>
          <Button
            type='button'
            size='sm'
