'use client';

import { AnimatePresence, motion } from 'motion/react';

import { useKeptHeight } from '@/registry/ndeko/hooks/use-kept-height';
import { usePrefersReducedMotion } from '@/registry/ndeko/hooks/use-prefers-reduced-motion';
import { useSession } from '@/registry/ndeko/hooks/use-session';
import {
  type PlanStep,
  type RunSnapshot,
  type RunStatus,
  seriesColorOf,
  type StepStatus,
  type ToolCall,
} from '@/registry/ndeko/lib/agent-run';
import { spokenUnless } from '@/registry/ndeko/lib/demonstration';
import { LoaderIcon } from '@/registry/ndeko/lib/icons';
import { rowPresenceOf } from '@/registry/ndeko/lib/motion-presets';
import { cn } from '@/registry/ndeko/lib/utils';
import { BrandTile } from '@/registry/ndeko/ui/brand-tile';
import { CallStatusMark } from '@/registry/ndeko/ui/call-status';
import { Fold, Swap } from '@/registry/ndeko/ui/chat-motion';
import { DrawnCheck } from '@/registry/ndeko/ui/drawn-check';
import { ClockGate, LiveDuration } from '@/registry/ndeko/ui/live-duration';
import { LiveRegion } from '@/registry/ndeko/ui/live-region';
import { MeshTile } from '@/registry/ndeko/ui/mesh-tile';
import { ReplayButton } from '@/registry/ndeko/ui/replay-button';
import { Wash } from '@/registry/ndeko/ui/wash';

import { AGENT, type Tool, type ToolId, TOOLS } from './run-data';
import { SESSION } from './run-script';

const AGENT_COLOR = seriesColorOf(1);

const STEP_WORD: Record<StepStatus, string> = {
  upcoming: 'Upcoming',
  running: 'Running',
  done: 'Done',
  failed: 'Failed',
  skipped: 'Skipped',
};

const RUN_WORD: Record<RunStatus, string> = {
  idle: 'Queued',
  running: 'Running',
  waiting: 'Waiting',
  done: 'Done',
  failed: 'Failed',
  cancelled: 'Stopped',
};

const DONE_MESSAGE =
  'Run finished: 398 bank lines matched, 14 left for you and 9 journal entries drafted.';

function isToolId(value: string): value is ToolId {
  return Object.hasOwn(TOOLS, value);
}

function toolOf(call: ToolCall): Tool | null {
  if (!isToolId(call.tool)) {
    return null;
  }
  return TOOLS[call.tool];
}

function resultOf(call: ToolCall) {
  if (typeof call.output === 'string') {
    return call.output;
  }
  return '';
}

function announcementOf(run: RunSnapshot) {
  if (run.status === 'done') {
    return DONE_MESSAGE;
  }
  return '';
}

function StepGlyph({ status }: { status: StepStatus }) {
  if (status === 'done') {
    return <DrawnCheck tone='success' entrance='draw' />;
  }
  if (status === 'running') {
    return <LoaderIcon className='text-muted-foreground size-4 animate-spin' />;
  }
  return (
    <span className='hairline-ring ring-foreground/25 size-3.5 rounded-full' />
  );
}

function PlanRow({ step }: { step: PlanStep }) {
  const isUpcoming = step.status === 'upcoming';

  return (
    <li className='flex h-7 items-center gap-2.5 text-[13px]'>
      <span className='flex size-[18px] shrink-0 items-center justify-center'>
        <Swap swapKey={step.status}>
          <StepGlyph status={step.status} />
        </Swap>
      </span>
      <span
        className={cn(
          'min-w-0 flex-1 truncate transition-colors duration-200',
          isUpcoming && 'text-muted-foreground'
        )}
      >
        <span className='sr-only'>{STEP_WORD[step.status]}: </span>
        {step.title}
      </span>
    </li>
  );
}

/** What a call found unfolds under it once it is done; its time sits in a box of its own width. */
function CallRow({ call }: { call: ToolCall }) {
  const tool = toolOf(call);
  const isRunning = call.status === 'running';
  const isDone = call.status === 'done';
  const result = resultOf(call);

  return (
    <div className='flex items-start gap-2.5 pb-2'>
      {tool && <BrandTile brand={tool.brand} size='lg' title={tool.name} />}
      <div className='flex min-w-0 flex-1 flex-col'>
        <p className='py-1 text-[13px] leading-5 text-pretty'>{call.label}</p>
        <Fold open={isDone}>
          <p className='text-muted-foreground text-xs text-pretty'>{result}</p>
        </Fold>
      </div>
      <span className='flex h-7 shrink-0 items-center gap-2'>
        <LiveDuration
          item={call}
          isRunning={isRunning}
          className='text-muted-foreground w-11 text-end text-xs'
        />
        <CallStatusMark status={call.status} />
      </span>
    </div>
  );
}

/**
 * A small run of the agent, playing beside the hero: the plan ticks while two tools are called
 * and their results unfold, under the ink of a run in progress. Clicking in it lets the run end;
 * Replay starts it again.
 */
export function LiveRun() {
  const {
    ref,
    isInView,
    isAutoplaying,
    state: run,
    isFinished,
    restart,
  } = useSession(SESSION);
  const shouldReduceMotion = usePrefersReducedMotion();
  const presence = rowPresenceOf(shouldReduceMotion);
  const isRunning = run.status === 'running';
  const runWord = RUN_WORD[run.status];
  const canReplay = isFinished && !isAutoplaying;
  const announcement = announcementOf(run);
  const message = spokenUnless(isAutoplaying, announcement);

  useKeptHeight(ref);

  return (
    <ClockGate isActive={isInView}>
      <div
        ref={ref}
        className='bg-card hairline-ring ring-border dark:bg-foreground/[0.03] flex min-h-[21rem] w-full flex-col rounded-2xl p-1.5 shadow-[0_1px_2px_rgb(0_0_0/0.04)]'
      >
        <div
          role='group'
          aria-label={`Run of ${AGENT.name}: ${run.title}`}
          className='bg-foreground/[0.03] relative isolate flex flex-1 flex-col gap-3 rounded-[calc(var(--radius-2xl)-0.375rem)] p-4'
        >
          <Wash color='var(--info)' isShown={isRunning} />
          <div className='flex items-center gap-2.5'>
            <MeshTile seed={AGENT.name} color={AGENT_COLOR} size='lg' />
            <div className='flex min-w-0 flex-1 flex-col'>
              <p className='truncate text-[13px] font-medium'>{AGENT.name}</p>
              <p className='text-muted-foreground truncate text-xs'>
                {run.title}
              </p>
            </div>
            <div className='flex shrink-0 flex-col items-end text-xs'>
              <Swap swapKey={runWord} className='font-medium'>
                {runWord}
              </Swap>
              <LiveDuration
                item={run}
                isRunning={isRunning}
                className='text-muted-foreground w-12 text-end'
              />
            </div>
          </div>
          <ol aria-label='Plan' className='flex flex-col'>
            {run.plan.map((step) => (
              <PlanRow key={step.id} step={step} />
            ))}
          </ol>
          <ul aria-label='Tool calls' className='flex flex-col'>
            <AnimatePresence initial={false}>
              {run.calls.map((call) => (
                <motion.li
                  key={call.id}
                  {...presence}
                  className='overflow-hidden'
                >
                  <CallRow call={call} />
                </motion.li>
              ))}
            </AnimatePresence>
          </ul>
        </div>
        <div className='flex min-h-9 items-center justify-between gap-2 ps-2.5 pe-1'>
          <span className='text-muted-foreground text-xs'>
            Illustrative run
          </span>
          <ReplayButton isShown={canReplay} onReplay={restart} />
        </div>
        <LiveRegion message={message} />
      </div>
    </ClockGate>
  );
}

'use client';

import { useRef, useState } from 'react';

import { MenuIcon } from '@/registry/ndeko/lib/icons';
import { Button } from '@/registry/ndeko/ui/button';
import { CompanyMark } from '@/registry/ndeko/ui/company-mark';
import { SelectedMark } from '@/registry/ndeko/ui/selected-mark';
import {
  Sheet,
  SheetContent,
  SheetDescription,
  SheetFooter,
  SheetHeader,
  SheetTitle,
  SheetTrigger,
} from '@/registry/ndeko/ui/sheet';

import { BRAND, HEADER, type NavLink } from './data';
import { scrollToSection, sectionHashOf } from './section-link';

function currentAttributeOf(isCurrent: boolean) {
  if (isCurrent) {
    return 'page' as const;
  }
  return undefined;
}

type MobileSheetProps = {
  links: NavLink[];
  currentId: string | null;
};

export function MobileSheet({ links, currentId }: MobileSheetProps) {
  const [isOpen, setIsOpen] = useState(false);
  const [shouldReturnFocus, setShouldReturnFocus] = useState(true);
  const pendingHashRef = useRef<string | null>(null);

  function changeOpen(open: boolean) {
    if (open) {
      setShouldReturnFocus(true);
    }
    setIsOpen(open);
  }

  function followLink(event: React.MouseEvent<HTMLElement>) {
    const href = event.currentTarget.getAttribute('href');
    const sectionHash = sectionHashOf(href);
    setShouldReturnFocus(false);
    setIsOpen(false);
    if (sectionHash === null) {
      return;
    }
    event.preventDefault();
    pendingHashRef.current = sectionHash;
  }

  function finishOpenChange(open: boolean) {
    const pendingHash = pendingHashRef.current;
    pendingHashRef.current = null;
    if (open) {
      return;
    }
    if (pendingHash === null) {
      return;
    }
    scrollToSection(pendingHash);
  }

  return (
    <Sheet
      open={isOpen}
      onOpenChange={changeOpen}
      onOpenChangeComplete={finishOpenChange}
    >
      <SheetTrigger
        render={
          <Button
            variant='ghost'
            size='icon'
            className='@2xl:hidden'
            aria-label='Open menu'
          />
        }
      >
        <MenuIcon />
      </SheetTrigger>
      <SheetContent side='right' finalFocus={shouldReturnFocus}>
        <SheetHeader>
          <SheetTitle className='flex items-center gap-2'>
            <CompanyMark seed={BRAND.name} size='lg' />
            {BRAND.name}
          </SheetTitle>
          <SheetDescription>{BRAND.tagline}</SheetDescription>
        </SheetHeader>
        <nav aria-label='Main'>
          <ul className='flex flex-col gap-0.5'>
            {links.map((link) => {
              const isCurrent = currentId === link.id;

              return (
                <li key={link.id}>
                  <a
                    href={link.href}
                    aria-current={currentAttributeOf(isCurrent)}
                    onClick={followLink}
                    className='text-foreground hover:bg-foreground/5 aria-[current=page]:bg-foreground/5 focus-visible:ring-ring/25 flex h-11 items-center justify-between rounded-md px-3 text-base font-medium transition-colors outline-none focus-visible:ring-[3px]'
                  >
                    {link.label}
                    {isCurrent && <SelectedMark />}
                  </a>
                </li>
              );
            })}
          </ul>
        </nav>
        <SheetFooter>
          <Button
            variant='outline'
            size='lg'
            nativeButton={false}
            render={<a href='#' />}
          >
            Sign in
          </Button>
          <Button
            size='lg'
            nativeButton={false}
            render={<a href={HEADER.actionHref} />}
            onClick={followLink}
          >
            {HEADER.action}
          </Button>
        </SheetFooter>
      </SheetContent>
    </Sheet>
  );
}

'use client';

import { AnimatePresence, motion, type Transition } from 'motion/react';
import { useState } from 'react';

import { usePrefersReducedMotion } from '@/registry/ndeko/hooks/use-prefers-reduced-motion';

import { type NavLink } from './data';

const HIGHLIGHT_TRANSITION: Transition = {
  type: 'spring',
  bounce: 0,
  duration: 0.3,
};

const INSTANT_LAYOUT: Transition = {
  layout: { duration: 0 },
  opacity: { duration: 0.15 },
};

function highlightTransitionOf(shouldReduceMotion: boolean | null) {
  if (shouldReduceMotion) {
    return INSTANT_LAYOUT;
  }
  return HIGHLIGHT_TRANSITION;
}

function currentAttributeOf(isCurrent: boolean) {
  if (isCurrent) {
    return 'page' as const;
  }
  return undefined;
}

type NavLinksProps = {
  links: NavLink[];
  currentId: string | null;
};

export function NavLinks({ links, currentId }: NavLinksProps) {
  const [hoveredId, setHoveredId] = useState<string | null>(null);
  const shouldReduceMotion = usePrefersReducedMotion();
  const highlightTransition = highlightTransitionOf(shouldReduceMotion);

  function clearHover() {
    setHoveredId(null);
  }

  return (
    <nav aria-label='Main' className='hidden @2xl:block'>
      <ul className='flex items-center' onPointerLeave={clearHover}>
        {links.map((link) => {
          const isHovered = hoveredId === link.id;
          const isCurrent = currentId === link.id;

          function highlight() {
            setHoveredId(link.id);
          }

          return (
            <li key={link.id}>
              <a
                href={link.href}
                aria-current={currentAttributeOf(isCurrent)}
                onPointerEnter={highlight}
                onFocus={highlight}
                onBlur={clearHover}
                className='text-muted-foreground hover:text-foreground aria-[current=page]:text-foreground focus-visible:ring-ring/25 relative inline-flex h-8 items-center rounded-full px-3 text-[13px] font-medium transition-colors outline-none focus-visible:ring-[3px]'
              >
                <AnimatePresence>
                  {isHovered && (
                    <motion.span
                      layoutId='marketing-06-nav-highlight'
                      aria-hidden='true'
                      className='bg-foreground/5 absolute inset-0 rounded-full'
                      initial={{ opacity: 0 }}
                      animate={{ opacity: 1 }}
                      exit={{ opacity: 0 }}
                      transition={highlightTransition}
                    />
                  )}
                </AnimatePresence>
                <span className='relative'>{link.label}</span>
              </a>
            </li>
          );
        })}
      </ul>
    </nav>
  );
}

'use client';

import { pressedQuietOf } from '@/registry/ndeko/lib/demonstration';
import { cn } from '@/registry/ndeko/lib/utils';
import { ToggleGroup, ToggleGroupItem } from '@/registry/ndeko/ui/toggle-group';

import { PERIODS, type PeriodId } from './figures-data';

const THUMB =
  'bg-card shadow-[0_1px_2px_rgb(0_0_0/0.08)] hairline-ring ring-foreground/10 dark:bg-foreground/[0.09] dark:ring-foreground/15';

type PeriodSwitchProps = {
  value: PeriodId;
  pressed: PeriodId | null;
  onValueChange: (period: PeriodId) => void;
};

export function PeriodSwitch({
  value,
  pressed,
  onValueChange,
}: PeriodSwitchProps) {
  const pressedValues = [value];

  /** Pressing the period already shown would leave nothing pressed: it stays. */
  function change(nextValues: unknown[]) {
    const [nextValue] = nextValues;
    const period = PERIODS.find((candidate) => candidate.id === nextValue);
    if (period) {
      onValueChange(period.id);
    }
  }

  return (
    <ToggleGroup
      aria-label='Period of the figures'
      value={pressedValues}
      onValueChange={change}
      travel
      size='sm'
      indicatorClassName={THUMB}
      className='bg-foreground/[0.05] rounded-lg p-0.5'
    >
      {PERIODS.map((period) => (
        <ToggleGroupItem
          key={period.id}
          value={period.id}
          className={cn(
            'h-7 rounded-md px-2.5 text-xs',
            pressedQuietOf(pressed === period.id)
          )}
        >
          {period.label}
        </ToggleGroupItem>
      ))}
    </ToggleGroup>
  );
}

'use client';

import { AnimatePresence, motion, type Transition } from 'motion/react';

import { MotionNumber } from '@/components/core/motion-number';
import { usePrefersReducedMotion } from '@/registry/ndeko/hooks/use-prefers-reduced-motion';
import { EASE_OUT_STRONG } from '@/registry/ndeko/lib/motion-presets';
import { cn } from '@/registry/ndeko/lib/utils';
import { Button } from '@/registry/ndeko/ui/button';
import { Chip } from '@/registry/ndeko/ui/chip';
import { Wash } from '@/registry/ndeko/ui/wash';

import type { Plan } from './pricing-data';
import {
  costOf,
  formatPrice,
  formatRate,
  formatVolume,
  PRICE_FORMAT,
} from './volume-model';

const RESTING_SURFACE =
  'bg-card hairline-ring ring-border shadow-[0_1px_2px_rgb(0_0_0/0.04)] dark:bg-foreground/[0.03]';

const LIFTED_SURFACE = 'surface-brand -translate-y-1';

const CHIP_SHOWN = { opacity: 1, scale: 1 };

const CHIP_HIDDEN = { opacity: 0, scale: 0.95 };

const CHIP_FADE = { opacity: 0 };

const CHIP_TRANSITION: Transition = { duration: 0.18, ease: EASE_OUT_STRONG };

function surfaceOf(isCheapest: boolean) {
  if (isCheapest) {
    return LIFTED_SURFACE;
  }
  return RESTING_SURFACE;
}

function actionVariantOf(isCheapest: boolean) {
  if (isCheapest) {
    return 'default' as const;
  }
  return 'outline' as const;
}

function chipHiddenOf(shouldReduceMotion: boolean) {
  if (shouldReduceMotion) {
    return CHIP_FADE;
  }
  return CHIP_HIDDEN;
}

type PlanCardProps = {
  plan: Plan;
  volume: number;
  isCheapest: boolean;
};

/** One plan priced for the volume of the sentence; the cheapest one lifts out of the row. */
export function PlanCard({ plan, volume, isCheapest }: PlanCardProps) {
  const shouldReduceMotion = usePrefersReducedMotion();
  const cost = costOf(plan, volume);
  const price = Math.round(cost);
  const basePrice = formatPrice(plan.basePrice);
  const included = formatVolume(plan.includedLines);
  const rate = formatRate(plan.pricePerThousand);
  const chipHidden = chipHiddenOf(shouldReduceMotion);

  return (
    <article
      className={cn(
        'relative isolate flex flex-col gap-5 rounded-xl p-5 transition-[translate,box-shadow] duration-300 ease-(--ease-out-strong)',
        surfaceOf(isCheapest)
      )}
    >
      <Wash isShown={isCheapest} />
      <div className='flex flex-col gap-1'>
        <div className='flex min-h-5 items-center justify-between gap-2'>
          <h3 className='text-sm font-medium'>{plan.name}</h3>
          <AnimatePresence initial={false}>
            {isCheapest && (
              <motion.span
                key='cheapest'
                initial={chipHidden}
                animate={CHIP_SHOWN}
                exit={chipHidden}
                transition={CHIP_TRANSITION}
                className='inline-flex'
              >
                <Chip>Cheapest for you</Chip>
              </motion.span>
            )}
          </AnimatePresence>
        </div>
        <p className='text-muted-foreground text-[13px] text-pretty'>
          {plan.summary}
        </p>
      </div>
      <p className='flex items-baseline gap-1.5'>
        <MotionNumber
          value={price}
          format={PRICE_FORMAT}
          className='text-4xl font-semibold'
        />
        <span className='text-muted-foreground text-[13px]'>a month</span>
      </p>
      <ul className='text-muted-foreground flex flex-col gap-1 text-xs tabular-nums'>
        <li>{basePrice} base price</li>
        <li>{included} bank lines included</li>
        <li>{rate} per 1,000 after that</li>
      </ul>
      <Button
        size='lg'
        variant={actionVariantOf(isCheapest)}
        nativeButton={false}
        render={<a href='#' />}
        className='mt-auto'
      >
        {plan.action}
      </Button>
    </article>
  );
}

