import {
  cheapestPlanAt,
  clampVolume,
  positionOf,
  volumeAt,
  volumeOfText,
} from './volume-model';
import { VolumeSentence } from './volume-sentence';
import { VolumeTrack } from './volume-track';

/** Where the demonstration drags the volume: past both notches, to where Firm becomes the cheapest. */
const DEMO_SCRUB_TO = 120_000;

/** What the demonstration then types, back in the stretch where Starter is the cheapest. */
const DEMO_TYPED = '2500';

/** The pause between two stops when the demonstration drags the number. */
const SCRUB_STEP_MS = 130;

const LOOP_AFTER_MS = 3000;

/** A drag of the demonstration from stop to stop, through the same handler a hand uses. */
function scrubSteps(
  from: number,
  to: number,
  write: (volume: number) => void,
  startAfter: number
): AutoplayStep[] {
  const firstPosition = Math.round(positionOf(from));
  const lastPosition = Math.round(positionOf(to));
  const distance = lastPosition - firstPosition;
  const direction = Math.sign(distance);
  const count = Math.abs(distance);
  const indexes = Array.from({ length: count }, (_, index) => index);
  return indexes.map((index) => {
    const walked = index + 1;
    const offset = walked * direction;
    const position = firstPosition + offset;
    const volume = volumeAt(position);
    const after = keyDelayOf(index, startAfter, SCRUB_STEP_MS);
    return { after, run: () => write(volume) };
  });
}

function announcementOf(cheapest: Plan, isOverLimit: boolean) {
  if (isOverLimit) {
    return SECTION.over;
  }
  return `${cheapest.name} is the cheapest plan at this volume.`;
}

export function Pricing() {
  const [volume, setVolume] = useState(START_VOLUME);
  const [draft, setDraft] = useState<string | null>(null);
  const [isOverLimit, setIsOverLimit] = useState(false);
  const [isDemoScrubbing, setIsDemoScrubbing] = useState(false);
  const hintId = useId();
  const cheapest = cheapestPlanAt(volume);

  function type(text: string) {
    setDraft(text);
    const typed = volumeOfText(text);
    if (typed === null) {
      setIsOverLimit(false);
      return;
    }
    const isOver = typed > MAX_VOLUME;
    const next = clampVolume(typed);
    setVolume(next);
    setIsOverLimit(isOver);
  }

  function commit() {
    setDraft(null);
  }

  function scrubTo(next: number) {
    setVolume(next);
    setDraft(null);
    setIsOverLimit(false);
  }

  function startOver() {
    setVolume(START_VOLUME);
    setDraft(null);
    setIsOverLimit(false);
    setIsDemoScrubbing(false);
  }

  const steps: AutoplayStep[] = [
    { after: 1300, run: () => setIsDemoScrubbing(true) },
    ...scrubSteps(START_VOLUME, DEMO_SCRUB_TO, scrubTo, 180),
    { after: 260, run: () => setIsDemoScrubbing(false) },
    { after: 1800, run: () => type('') },
    ...typingSteps(DEMO_TYPED, type, { startAfter: 420, characterMs: 170 }),
    { after: 600, run: commit },
  ];
  const { ref, isAutoplaying } = useAutoplay<HTMLElement>(steps, {
    loopAfter: LOOP_AFTER_MS,
    onReset: startOver,
  });
  /** A person who takes over in the middle of the drag lets go of the number. */
  const showsDemoScrub = isDemoScrubbing && isAutoplaying;
  const announcement = announcementOf(cheapest, isOverLimit);
  const message = spokenUnless(isAutoplaying, announcement);

  useKeptHeight(ref);

  return (
    <SectionFrame id={ANCHORS.pricing} ref={ref}>
      <SectionHeader
        icon={TicketPercentIcon}
        label={SECTION.label}
        title={SECTION.title}
        lead={SECTION.lead}
      />
      <div className='flex flex-col gap-6'>
        <VolumeSentence
          volume={volume}
          draft={draft}
          isOverLimit={isOverLimit}
          isDemoScrubbing={showsDemoScrub}
          hintId={hintId}
          onType={type}
          onCommit={commit}
          onScrub={scrubTo}
        />
        <VolumeTrack
          volume={volume}
          cheapest={cheapest}
          onVolumeChange={scrubTo}
        />
      </div>
      <div className='grid gap-4 @3xl:grid-cols-3'>
        {PLANS.map((plan) => (
          <PlanCard
            key={plan.id}
            plan={plan}
            volume={volume}
            isCheapest={plan === cheapest}
          />
        ))}
      </div>
      <p className='text-muted-foreground text-xs'>{SECTION.footnote}</p>
      <LiveRegion message={message} />
    </SectionFrame>
  );
}

'use client';

import { motion, type Transition } from 'motion/react';
import type { CSSProperties } from 'react';

import { usePrefersReducedMotion } from '@/registry/ndeko/hooks/use-prefers-reduced-motion';
import { EASE_OUT_STRONG, INSTANT } from '@/registry/ndeko/lib/motion-presets';
import { cn } from '@/registry/ndeko/lib/utils';

const GLIDE: Transition = { duration: 0.5, ease: EASE_OUT_STRONG };

const PLOT = {
  width: 320,
  height: 72,
  top: 6,
  bottom: 2,
};

const VIEW_BOX = `0 0 ${PLOT.width} ${PLOT.height}`;

const BASELINE_Y = PLOT.height - 0.5;

function easedOf(shouldReduceMotion: boolean) {
  if (shouldReduceMotion) {
    return 'transition-none';
  }
  return 'transition-transform duration-500 ease-(--ease-out-strong)';
}

function glideOf(shouldReduceMotion: boolean) {
  if (shouldReduceMotion) {
    return INSTANT;
  }
  return GLIDE;
}

function plotHeightOf() {
  const margins = PLOT.top + PLOT.bottom;
  return PLOT.height - margins;
}

type Point = { x: number; y: number };

function pointsOf(values: readonly number[], max: number): Point[] {
  const lastPosition = values.length - 1;
  const lastIndex = Math.max(1, lastPosition);
  const plotHeight = plotHeightOf();
  return values.map((value, index) => {
    const share = index / lastIndex;
    const x = share * PLOT.width;
    const level = value / max;
    const drop = 1 - level;
    const offset = drop * plotHeight;
    const y = PLOT.top + offset;
    return { x, y };
  });
}

function commandOf(index: number) {
  if (index === 0) {
    return 'M';
  }
  return 'L';
}

function segmentOf(point: Point, index: number) {
  const x = point.x.toFixed(2);
  const y = point.y.toFixed(2);
  const command = commandOf(index);
  return `${command} ${x} ${y}`;
}

/** Every period has as many points, so the two outlines share one structure and the path can glide. */
function linePathOf(points: Point[]) {
  const segments = points.map((point, index) => segmentOf(point, index));
  return segments.join(' ');
}

function areaPathOf(line: string) {
  return `${line} L ${PLOT.width} ${PLOT.height} L 0 ${PLOT.height} Z`;
}

function rowNameOf(pointName: string, index: number) {
  const position = index + 1;
  return `${pointName} ${position}`;
}

type TrendLineProps = {
  values: readonly number[];
  max: number;
  caption: string;
  pointName: string;
  formatValue: (value: number) => string;
};

export function TrendLine({
  values,
  max,
  caption,
  pointName,
  formatValue,
}: TrendLineProps) {
  const shouldReduceMotion = usePrefersReducedMotion();
  const transition = glideOf(shouldReduceMotion);
  const points = pointsOf(values, max);
  const line = linePathOf(points);
  const area = areaPathOf(line);

  return (
    <div className='relative'>
      <svg
        viewBox={VIEW_BOX}
        preserveAspectRatio='none'
        aria-hidden='true'
        className='h-16 w-full overflow-visible'
      >
        <line
          x1={0}
          x2={PLOT.width}
          y1={BASELINE_Y}
          y2={BASELINE_Y}
          strokeWidth={1}
          vectorEffect='non-scaling-stroke'
          className='stroke-border'
        />
        <motion.path
          initial={false}
          animate={{ d: area }}
          transition={transition}
          className='fill-primary/10'
        />
        <motion.path
          initial={false}
          animate={{ d: line }}
          transition={transition}
          fill='none'
          strokeWidth={2}
          strokeLinecap='round'
          strokeLinejoin='round'
          vectorEffect='non-scaling-stroke'
          className='stroke-primary'
        />
      </svg>
      <div className='sr-only'>
        <table>
          <caption>{caption}</caption>
          <tbody>
            {values.map((value, index) => (
              <tr key={index}>
                <th scope='row'>{rowNameOf(pointName, index)}</th>
                <td>{formatValue(value)}</td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>
    </div>
  );
}

function barStyleOf(percent: number): CSSProperties {
  const share = percent / 100;
  return { transform: `scaleY(${share})` };
}

type WeekdayBarsProps = {
  values: readonly number[];
  days: readonly string[];
  caption: string;
};

export function WeekdayBars({ values, days, caption }: WeekdayBarsProps) {
  const shouldReduceMotion = usePrefersReducedMotion();
  const eased = easedOf(shouldReduceMotion);

  return (
    <div className='relative flex flex-col gap-1.5'>
      <div aria-hidden='true' className='flex h-16 items-end gap-1.5'>
        {values.map((value, index) => (
          <span
            key={days[index]}
            style={barStyleOf(value)}
            className={cn(
              'bg-primary h-full flex-1 origin-bottom rounded-[3px]',
              eased
            )}
          />
        ))}
      </div>
      <div aria-hidden='true' className='flex gap-1.5'>
        {days.map((day) => (
          <span
            key={day}
            className='text-muted-foreground flex-1 text-center text-[10px]'
          >
            {day.charAt(0)}
          </span>
        ))}
      </div>
      <div className='sr-only'>
        <table>
          <caption>{caption}</caption>
          <tbody>
            {values.map((value, index) => (
              <tr key={days[index]}>
                <th scope='row'>{days[index]}</th>
                <td>{value}%</td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>
    </div>
  );
}

function fillStyleOf(percent: number): CSSProperties {
  const share = percent / 100;
  return { transform: `scaleX(${share})` };
}

type DistributionProps = {
  values: readonly number[];
  buckets: readonly string[];
  caption: string;
};

export function Distribution({ values, buckets, caption }: DistributionProps) {
  const shouldReduceMotion = usePrefersReducedMotion();
  const eased = easedOf(shouldReduceMotion);

  return (
    <div className='relative'>
      <ul aria-hidden='true' className='flex flex-col gap-2'>
        {values.map((value, index) => (
          <li
            key={buckets[index]}
