                  eased
                )}
              />
            </span>
            <span className='text-end tabular-nums'>{value}%</span>
          </li>
        ))}
      </ul>
      <div className='sr-only'>
        <table>
          <caption>{caption}</caption>
          <tbody>
            {values.map((value, index) => (
              <tr key={buckets[index]}>
                <th scope='row'>{buckets[index]}</th>
                <td>{value}%</td>
