/** Long enough to read a featured quote once it has written itself in. */
const FEATURE_MS = 6200;

function indexAfter(index: number) {
  const next = index + 1;
  return next % CUSTOMERS.length;
}

/** The next customer after each one, so a round ends on the first customer and the loop shows no seam. */
const ROTATION = CUSTOMERS.map((_, index) => indexAfter(index));

function spokenFeatureOf(index: number) {
  const { company, result } = CUSTOMERS[index];
  return `Featured: ${company}, ${result.percent}% ${result.label}`;
}

export function Testimonials() {
  const [featuredIndex, setFeaturedIndex] = useState(0);
  const [hasChanged, setHasChanged] = useState(false);
  const [isReading, setIsReading] = useState(false);
  const [message, setMessage] = useState('');
  const { pressed, press } = usePress<string>();
  const featured = CUSTOMERS[featuredIndex];

  function feature(index: number) {
    setFeaturedIndex(index);
    setHasChanged(true);
  }

  const steps = ROTATION.flatMap((index) => [
    { after: FEATURE_MS, run: () => press(CUSTOMERS[index].id) },
    { after: PRESS_LEAD_MS, run: () => feature(index) },
  ]);
  const { ref } = useAutoplay<HTMLElement>(steps, {
    loopAfter: 0,
    isEnabled: !isReading,
  });

  function featureByPerson(customerId: string) {
    const index = CUSTOMERS.findIndex((customer) => customer.id === customerId);
    feature(index);
    setMessage(spokenFeatureOf(index));
  }

  /** The featured quote does not change under the pointer of someone reading it. */
  function holdWhileReading(event: React.PointerEvent<HTMLDivElement>) {
    if (event.pointerType === 'mouse') {
      setIsReading(true);
    }
  }

  function stopReading() {
    setIsReading(false);
  }

  return (
    <SectionFrame id={ANCHORS.customers} ref={ref}>
      <SectionHeader
        icon={TrendingUpIcon}
        label={SECTION.label}
        title={SECTION.title}
        lead={SECTION.lead}
      >
        <Badge variant='secondary'>Sample quotes</Badge>
        <Badge variant='secondary'>Illustrative figures</Badge>
      </SectionHeader>
      <div className='flex flex-col gap-4'>
        <div onPointerEnter={holdWhileReading} onPointerLeave={stopReading}>
          <FeaturedResult
            customer={featured}
            position={featuredIndex}
            isStreamed={hasChanged}
          />
        </div>
        <ul className='grid gap-3 @xl:grid-cols-2 @4xl:grid-cols-3'>
          {CUSTOMERS.map((customer, index) => (
            <li key={customer.id}>
              <WallCard
                customer={customer}
                isFeatured={index === featuredIndex}
                isPressed={pressed === customer.id}
                onFeature={featureByPerson}
              />
            </li>
          ))}
        </ul>
      </div>
      <LiveRegion message={message} />
    </SectionFrame>
  );
}

import { MAX_VOLUME, type Plan, PLANS, STOPS } from './pricing-data';

/** A place on the track where another plan becomes the cheapest. */
export type Notch = {
  volume: number;
  position: number;
  plan: Plan;
};

/** The stretch of the track where one plan is the cheapest. */
export type Zone = {
  plan: Plan;
  from: number;
  to: number;
};

export const LAST_POSITION = STOPS.length - 1;

const FIRST_STOP = STOPS[0];

export const PRICE_FORMAT: Intl.NumberFormatOptions = {
  style: 'currency',
  currency: 'USD',
  maximumFractionDigits: 0,
};

const PRICE_FORMATTER = new Intl.NumberFormat('en-US', PRICE_FORMAT);

const RATE_FORMATTER = new Intl.NumberFormat('en-US', {
  style: 'currency',
  currency: 'USD',
  minimumFractionDigits: 2,
  maximumFractionDigits: 2,
});

const VOLUME_FORMATTER = new Intl.NumberFormat('en-US');

const NOT_DIGITS = /\D/g;

export function formatPrice(amount: number) {
  return PRICE_FORMATTER.format(amount);
}

export function formatRate(amount: number) {
  return RATE_FORMATTER.format(amount);
}

export function formatVolume(volume: number) {
  return VOLUME_FORMATTER.format(volume);
}

/** The number in a typed text, whatever separators came with it; null while nothing is typed. */
export function volumeOfText(text: string) {
  const digits = text.replace(NOT_DIGITS, '');
  if (digits === '') {
    return null;
  }
  return Number(digits);
}

export function clampVolume(volume: number) {
  const atLeastZero = Math.max(volume, 0);
  return Math.min(atLeastZero, MAX_VOLUME);
}

export function costOf(plan: Plan, volume: number) {
  const over = volume - plan.includedLines;
  const billable = Math.max(0, over);
  const thousands = billable / 1_000;
  const overage = thousands * plan.pricePerThousand;
  return plan.basePrice + overage;
}

/** The plan that costs the least for this volume. A tie goes to the smaller plan. */
export function cheapestPlanAt(volume: number) {
  let cheapest = PLANS[0];
  let lowest = costOf(cheapest, volume);
  for (const plan of PLANS) {
    const cost = costOf(plan, volume);
    if (cost < lowest) {
      cheapest = plan;
      lowest = cost;
    }
  }
  return cheapest;
}

/** Where a volume sits on the track: on a stop, or between two stops on a log scale. */
export function positionOf(volume: number) {
  if (volume <= FIRST_STOP) {
    return 0;
  }
  for (let index = 0; index < LAST_POSITION; index += 1) {
    const low = STOPS[index];
    const high = STOPS[index + 1];
    if (volume <= high) {
      const covered = Math.log(volume / low);
      const span = Math.log(high / low);
      const along = covered / span;
      return index + along;
    }
  }
  return LAST_POSITION;
}

export function volumeAt(position: number) {
  const index = Math.round(position);
  const atLeastFirst = Math.max(index, 0);
  const bounded = Math.min(atLeastFirst, LAST_POSITION);
  return STOPS[bounded];
}

export function shareOf(position: number) {
  return position / LAST_POSITION;
}

/** The arrow keys go from stop to stop, starting from any typed volume. */
export function stopAbove(volume: number) {
  const stop = STOPS.find((candidate) => candidate > volume);
  if (stop === undefined) {
    return MAX_VOLUME;
  }
  return stop;
}

/** Under the first stop there is nowhere lower to go, so a typed 300 stays 300 instead of rising to it. */
export function stopBelow(volume: number) {
  const lower = STOPS.filter((candidate) => candidate < volume);
  const stop = lower.at(-1);
  if (stop === undefined) {
    return volume;
  }
  return stop;
}

/** The smallest volume past `low` where the cheapest plan is no longer the one at `low`. */
function firstVolumeOfChange(low: number, high: number) {
  const before = cheapestPlanAt(low);
  let below = low;
  let above = high;
  while (above - below > 1) {
    const sum = below + above;
    const middle = Math.floor(sum / 2);
    const plan = cheapestPlanAt(middle);
    if (plan === before) {
      below = middle;
    } else {
      above = middle;
    }
  }
  return above;
}

function notchesOf() {
  const notches: Notch[] = [];
  for (let index = 0; index < LAST_POSITION; index += 1) {
    const low = STOPS[index];
    const high = STOPS[index + 1];
    const lowPlan = cheapestPlanAt(low);
    const highPlan = cheapestPlanAt(high);
    if (lowPlan === highPlan) {
      continue;
    }
    const volume = firstVolumeOfChange(low, high);
    const position = positionOf(volume);
    notches.push({ volume, position, plan: highPlan });
  }
  return notches;
}

function zonesOf(notches: readonly Notch[]) {
  const zones: Zone[] = [];
  let from = 0;
  let plan = cheapestPlanAt(FIRST_STOP);
  for (const notch of notches) {
    zones.push({ plan, from, to: notch.position });
    from = notch.position;
    plan = notch.plan;
  }
  zones.push({ plan, from, to: LAST_POSITION });
  return zones;
}

/** The prices are fixed, so the places where the cheapest plan changes are worked out once. */
export const NOTCHES = notchesOf();

export const ZONES = zonesOf(NOTCHES);

'use client';

import { AnimatePresence, motion } from 'motion/react';
import { useRef, useState } from 'react';

import { usePrefersReducedMotion } from '@/registry/ndeko/hooks/use-prefers-reduced-motion';
import { rowPresenceOf } from '@/registry/ndeko/lib/motion-presets';

import { SECTION } from './pricing-data';
import {
  formatVolume,
  positionOf,
  stopAbove,
  stopBelow,
  volumeAt,
} from './volume-model';

/** How far the pointer travels to reach the next stop when it drags the number. */
const PX_PER_STOP = 8;

/** Under this distance a press on the number is a click, and the click opens it for typing. */
const DRAG_THRESHOLD_PX = 4;

/** Room for "10,000,000" and one key more: a longer entry would push the sentence past the width of a phone. */
const MAX_TYPED_CHARACTERS = 11;

type DragStart = {
  x: number;
  position: number;
};

function describedByOf(isOverLimit: boolean, hintId: string) {
  if (isOverLimit) {
    return hintId;
  }
  return undefined;
}

function scrubbingOf(isScrubbing: boolean) {
  if (isScrubbing) {
    return 'true';
  }
  return undefined;
}

function isPrimaryPress(event: React.PointerEvent<HTMLInputElement>) {
  return event.button === 0;
}

/** A press let go outside the number never reaches its pointerup: the next move finds no button down. */
function isReleased(event: React.PointerEvent<HTMLInputElement>) {
  return event.buttons === 0;
}

function isFocused(element: HTMLElement) {
  return document.activeElement === element;
}

/** A press on the number while it is not being typed in may become a drag: no caret, no focus yet. */
function keepFocusAway(event: React.MouseEvent<HTMLInputElement>) {
  if (isFocused(event.currentTarget)) {
    return;
  }
  event.preventDefault();
}

type VolumeSentenceProps = {
  volume: number;
  /** What is typed in the number, while a person or the demonstration types; null shows the volume. */
  draft: string | null;
  isOverLimit: boolean;
  /** The demonstration drags the number: it wears the look of a hand on it. */
  isDemoScrubbing: boolean;
  hintId: string;
  onType: (text: string) => void;
  onCommit: () => void;
  onScrub: (volume: number) => void;
};

/**
 * "I reconcile 4,000 bank lines a month". The number is a field: drag it sideways to scrub through the
 * stops, click it to type, Up and Down step from stop to stop, Escape puts back what was there.
 * The field takes the width of a hidden copy of its text, so it is given no width of its own.
 */
export function VolumeSentence({
  volume,
  draft,
  isOverLimit,
  isDemoScrubbing,
  hintId,
  onType,
  onCommit,
  onScrub,
}: VolumeSentenceProps) {
  const [isScrubbing, setIsScrubbing] = useState(false);
  const dragStart = useRef<DragStart | null>(null);
  const hasDragged = useRef(false);
  const volumeAtFocus = useRef(volume);
  const shouldReduceMotion = usePrefersReducedMotion();
  const presence = rowPresenceOf(shouldReduceMotion);
  const formatted = formatVolume(volume);
  const shownText = draft ?? formatted;
  const isHandOnNumber = isScrubbing || isDemoScrubbing;

  function startDrag(event: React.PointerEvent<HTMLInputElement>) {
    if (!isPrimaryPress(event)) {
      return;
    }
    if (isFocused(event.currentTarget)) {
      return;
    }
    const position = positionOf(volume);
    dragStart.current = { x: event.clientX, position };
    hasDragged.current = false;
  }

  function drag(event: React.PointerEvent<HTMLInputElement>) {
    const start = dragStart.current;
    if (!start) {
      return;
    }
    if (isReleased(event)) {
      cancelDrag();
      return;
    }
    const travelled = event.clientX - start.x;
    const distance = Math.abs(travelled);
    const isStillAClick = !hasDragged.current && distance < DRAG_THRESHOLD_PX;
    if (isStillAClick) {
      return;
    }
    if (!hasDragged.current) {
      hasDragged.current = true;
      event.currentTarget.setPointerCapture(event.pointerId);
      setIsScrubbing(true);
    }
    const stops = travelled / PX_PER_STOP;
    const position = start.position + stops;
    const next = volumeAt(position);
    if (next !== volume) {
      onScrub(next);
    }
  }

  function endDrag(event: React.PointerEvent<HTMLInputElement>) {
    const start = dragStart.current;
    dragStart.current = null;
    if (!start) {
      return;
    }
    if (hasDragged.current) {
      setIsScrubbing(false);
      return;
    }
    const input = event.currentTarget;
    input.focus();
    input.select();
  }

  function cancelDrag() {
    dragStart.current = null;
    setIsScrubbing(false);
  }

  function rememberVolume(event: React.FocusEvent<HTMLInputElement>) {
    volumeAtFocus.current = volume;
    event.currentTarget.select();
  }

  function type(event: React.ChangeEvent<HTMLInputElement>) {
    onType(event.currentTarget.value);
  }

  function pressKey(event: React.KeyboardEvent<HTMLInputElement>) {
    if (event.key === 'ArrowUp') {
      event.preventDefault();
      onScrub(stopAbove(volume));
      return;
    }
    if (event.key === 'ArrowDown') {
      event.preventDefault();
      onScrub(stopBelow(volume));
      return;
    }
    if (event.key === 'Enter') {
      event.preventDefault();
      onCommit();
      return;
    }
    if (event.key === 'Escape') {
      event.preventDefault();
      onScrub(volumeAtFocus.current);
      onCommit();
    }
  }

  return (
    <div className='flex flex-col'>
      <p className='text-3xl leading-tight font-semibold text-balance @2xl:text-4xl @4xl:text-5xl'>
        I reconcile{' '}
        <span className='relative inline-grid align-baseline'>
          <span
            aria-hidden='true'
            className='invisible col-start-1 row-start-1 px-2 whitespace-pre tabular-nums'
          >
            {shownText}
          </span>
          <input
            type='text'
            size={1}
            maxLength={MAX_TYPED_CHARACTERS}
            inputMode='numeric'
            autoComplete='off'
            spellCheck={false}
            aria-label='Bank lines you reconcile each month'
            aria-describedby={describedByOf(isOverLimit, hintId)}
            data-scrubbing={scrubbingOf(isHandOnNumber)}
            value={shownText}
            onChange={type}
            onFocus={rememberVolume}
            onBlur={onCommit}
            onKeyDown={pressKey}
            onMouseDown={keepFocusAway}
            onPointerDown={startDrag}
            onPointerMove={drag}
            onPointerUp={endDrag}
            onPointerCancel={cancelDrag}
            className='bg-primary/10 text-primary-ink hover:bg-primary/15 focus-visible:ring-ring/25 data-scrubbing:bg-primary/20 col-start-1 row-start-1 w-full min-w-0 cursor-ew-resize touch-pan-y rounded-xl px-2 tabular-nums transition-[background-color,box-shadow] duration-150 outline-none focus:cursor-text focus-visible:ring-[3px]'
          />
        </span>{' '}
        bank lines a month
      </p>
      <AnimatePresence initial={false}>
        {isOverLimit && (
          <motion.p
            key='over'
            id={hintId}
            {...presence}
            className='text-warning-foreground overflow-hidden text-[13px] text-pretty'
          >
            <span className='block pt-3'>{SECTION.over}</span>
          </motion.p>
        )}
      </AnimatePresence>
    </div>
  );
}

